// Data Management Functions for Tabolator App
// This file contains all CRUD operations and data management logic

// ================================
// CATEGORY MANAGEMENT
// ================================

export const handleAddCategory = (categories, categoryInput, setCategories, setCategoryInput) => {
  if (categoryInput.trim()) {
    const newCategory = {
      id: Date.now(),
      name: categoryInput,
      created_at: new Date().toISOString()
    };
    setCategories([...categories, newCategory]);
    setCategoryInput('');

    // Also add to backend
    fetch('http://localhost/Tabolator_Casestudy/backend/api/categories', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        name: categoryInput
      })
    });
  }
};

export const handleDeleteCategory = (id, categories, setCategories) => {
  setCategories(categories.filter(cat => cat.id !== id));

  // Also delete from backend
  fetch(`http://localhost/Tabolator_Casestudy/backend/api/categories?id=${id}`, {
    method: 'DELETE'
  });
};

// ================================
// CRITERIA MANAGEMENT
// ================================

export const handleAddCriteria = (
  criteriaInput, 
  selectedCategory, 
  categories, 
  criteria, 
  setCriteria, 
  setCriteriaInput
) => {
  console.log('handleAddCriteria called with:', {
    criteriaInput,
    selectedCategory,
    categories: categories.length,
    criteria: criteria.length
  });

  // Validate inputs
  if (!criteriaInput.name?.trim()) {
    alert('Please enter a criteria name');
    return;
  }

  if (!criteriaInput.percentage || criteriaInput.percentage <= 0) {
    alert('Please enter a valid percentage greater than 0');
    return;
  }

  if (!criteriaInput.min || criteriaInput.min < 0) {
    alert('Please enter a valid minimum score (0 or greater)');
    return;
  }

  if (!criteriaInput.max || criteriaInput.max <= 0) {
    alert('Please enter a valid maximum score greater than 0');
    return;
  }

  if (parseFloat(criteriaInput.min) >= parseFloat(criteriaInput.max)) {
    alert('Maximum score must be greater than minimum score');
    return;
  }

  if (!selectedCategory) {
    alert('Please select a category');
    return;
  }

  const selectedCat = categories.find(cat => cat.name === selectedCategory);
  console.log('Selected category:', selectedCat);

  if (!selectedCat) {
    alert('Selected category not found. Please try again.');
    return;
  }

  // Prepare data for API
  const apiData = {
    category_id: selectedCat.id,
    name: criteriaInput.name.trim(),
    percentage: parseFloat(criteriaInput.percentage),
    min_score: parseFloat(criteriaInput.min),
    max_score: parseFloat(criteriaInput.max)
  };

  console.log('Sending to API:', apiData);

  // Call API first, then update local state
  fetch('http://localhost/Tabolator_Casestudy/backend/api/criteria', {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(apiData)
  })
  .then(response => {
    console.log('API Response:', response);
    if (!response.ok) {
      return response.json().then(err => {
        throw new Error(err.message || `HTTP error! status: ${response.status}`);
      });
    }
    return response.json();
  })
  .then(data => {
    console.log('API Response Data:', data);

    if (data.success) {
      // Update local state with the database response (includes real ID from database)
      const dbCriterion = data.data || {
        ...apiData,
        id: Date.now(), // Fallback ID if not provided
        category_name: selectedCategory
      };

      setCriteria([...criteria, dbCriterion]);
      setCriteriaInput({ name: '', percentage: '', min: '', max: '' });
      console.log('✅ Criteria saved to database successfully');
      alert('Criteria added successfully!');
    } else {
      console.error('❌ API Error:', data.message);
      // Show error to user
      alert('Failed to save criteria: ' + (data.message || 'Unknown error'));
    }
  })
  .catch(error => {
    console.error('❌ Network Error:', error);
    // Show error to user
    alert('Failed to save criteria: ' + error.message);
  });
};

export const handleEditCriteria = (criterion, categories, setSelectedCategory, setCriteriaInput) => {
  // Pre-fill the input fields with the selected criterion
  setCriteriaInput({
    name: criterion.name,
    percentage: criterion.percentage,
    min: criterion.min_score,
    max: criterion.max_score
  });

  // Find and set the category
  const category = categories.find(cat => cat.id === criterion.category_id);
  if (category) {
    setSelectedCategory(category.name);
  }
};

export const handleDeleteCriteria = (id, criteria, setCriteria) => {
  setCriteria(criteria.filter(crit => crit.id !== id));

  // Also delete from backend
  fetch(`http://localhost/Tabolator_Casestudy/backend/api/criteria?id=${id}`, {
    method: 'DELETE'
  });
};

// ================================
// JUDGE MANAGEMENT
// ================================

export const handleAddJudge = (judgeInput, judges, setJudges, setJudgeInput) => {
  if (judgeInput.trim()) {
    const pin = Math.floor(1000 + Math.random() * 9000).toString();
    const newJudge = {
      id: Date.now(),
      name: judgeInput,
      pin: pin
    };
    setJudges([...judges, newJudge]);
    setJudgeInput('');

    // Also add to backend
    fetch('http://localhost/Tabolator_Casestudy/backend/api/judges', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        name: judgeInput,
        pin: pin
      })
    });
  }
};

export const handleDeleteJudge = (id, judges, setJudges) => {
  setJudges(judges.filter(judge => judge.id !== id));

  // Also delete from backend
  fetch(`http://localhost/Tabolator_Casestudy/backend/api/judges?id=${id}`, {
    method: 'DELETE'
  });
};

// ================================
// CONTESTANT MANAGEMENT
// ================================

export const handleAddContestant = (contestantInput, contestants, setContestants, setContestantInput) => {
  if (contestantInput.trim()) {
    const newContestant = {
      id: Date.now(),
      name: contestantInput,
      status: 'Active',
      created_at: new Date().toISOString()
    };
    setContestants([...contestants, newContestant]);
    setContestantInput('');

    // Also add to backend
    fetch('http://localhost/Tabolator_Casestudy/backend/api/contestants', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        name: contestantInput,
        status: 'Active'
      })
    });
  }
};

export const handleDeleteContestant = (id, contestants, setContestants) => {
  setContestants(contestants.filter(contestant => contestant.id !== id));

  // Also delete from backend
  fetch(`http://localhost/Tabolator_Casestudy/backend/api/contestants?id=${id}`, {
    method: 'DELETE'
  });
};

export const handleEliminateContestant = (id, contestants, setContestants) => {
  setContestants(contestants.map(contestant => 
    contestant.id === id ? { ...contestant, status: 'Eliminated' } : contestant
  ));

  // Also update in backend
  fetch(`http://localhost/Tabolator_Casestudy/backend/api/contestants/${id}`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      status: 'Eliminated'
    })
  });
};

export const handleDisqualifyContestant = (id, contestants, setContestants) => {
  setContestants(contestants.map(contestant => 
    contestant.id === id ? { ...contestant, status: 'Disqualified' } : contestant
  ));

  // Also update in backend
  fetch(`http://localhost/Tabolator_Casestudy/backend/api/contestants/${id}`, {
    method: 'PUT',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      status: 'Disqualified'
    })
  });
};
